Case 3: Equality of both constructions
Save as same_order.go. Build one Order with promoted keys and one with a nested Table literal. Compare field by field.
// same_order.go
package main

import "fmt"

type Table struct {
    Number int
    Seats  int
}

type Order struct {
    Table
    Item  string
    Cents int
}

func main() {
    promoted := Order{
        Number: 4,
        Seats:  2,
