The trap
Save as promote_not_subtype.go. Promoted keys make construction look flatter. They do not make Order a Table. Functions that want Table still need o.Table.
// promote_not_subtype.go
package main

import "fmt"

type Table struct {
    Number int
    Seats  int
}

type Order struct {
    Table
    Item string
}

func freeSeats(t Table) int {
    return t.Seats
}

func main() {
    o := Order{
        Number: 4,
        Seats:  2,
        Item:   "tea",
