The trap
A common temptation in textbook Trie implementations is using a fixed ASCII array [26]*TrieNode for child pointers. While this avoids map allocations, it panics on uppercase letters, digits, dashes, and UTF-8 characters (ch - 'a' &lt; 0). In Go, strings are UTF-8 by default; using map[rune]*TrieNode safely handles spaces, punctuation, dashes, and non-English characters without buffer overruns.
// bad_ascii_trie.go
package main

import "fmt"

type BadNode struct {
    children [26]*BadNode // TRAP: Only supports lowercase a-z
}

func badInsert(root *BadNode, word string) {
    curr := root
    for _, ch := range word {
        // If word contains '-' or '0'..'9', index goes out of range!
        idx := ch - 'a'
        if idx &lt; 0 || idx &gt;= 26 {
            fmt.Printf("PANIC PREVENTED: rune '%c' is invalid for [26] array!\n", ch)
            return
        }
        if curr.children[idx] == nil {
            curr.children[idx] = &BadNode{}
        }
        curr = curr.children[idx]
    }
}

func main() {
    root := &BadNode{}
    badInsert(root, "DESK-101")
}
