Case 1: Setting GOMEMLIMIT and observing pointer scan times
Save as gc_demo.go. We inspect how debug.SetMemoryLimit works and compare GC pause times between pointer-heavy structs and pointer-free structs.
// gc_demo.go
package main

import (
    "fmt"
    "runtime"
    "runtime/debug"
    "time"
)

type PointerTicket struct {
    ID    *int
    Label *string
}

type FlatTicket struct {
    ID    int
    Code  int64
    Price int64
}

func main() {
    // Query current limit (math.MaxInt64 by default)
    oldLimit := debug.SetMemoryLimit(-1)
    fmt.Printf("Current GOMEMLIMIT: %d bytes\n", oldLimit)

    // Set soft limit to 256 MB (programmatic equivalent of GOMEMLIMIT=256MiB)
    newLimit := int64(256 * 1024 * 1024)
    debug.SetMemoryLimit(newLimit)
    fmt.Printf("Configured GOMEMLIMIT: %d MB\n", debug.SetMemoryLimit(-1)/(1024*1024))

    const n = 1_000_000

    // 1. Slice of pointer-heavy structs
    idVal := 42
    lblVal := "STANDARD-TICKET"
    ptrList := make([]PointerTicket, n)
    for i := range n {
        ptrList[i] = PointerTicket{ID: &idVal, Label: &lblVal}
    }

    start := time.Now()
    runtime.GC()
    ptrGCTime := time.Since(start)

    // Clear pointer slice before second test
    ptrList = nil
    runtime.GC()

    // 2. Slice of pointer-free structs
    flatList := make([]FlatTicket, n)
    for i := range n {
        flatList[i] = FlatTicket{ID: i, Code: int64(i * 10), Price: 500}
    }

    start = time.Now()
    runtime.GC()
    flatGCTime := time.Since(start)

    _ = flatList

    fmt.Printf("GC scan time with 1M pointer structs:     %v\n", ptrGCTime)
    fmt.Printf("GC scan time with 1M pointer-free structs: %v\n", flatGCTime)
}
Run:
go run gc_demo.go
Output:
Current GOMEMLIMIT: 9223372036854775807 bytes
Configured GOMEMLIMIT: 256 MB
GC scan time with 1M pointer structs:     1.01824ms
GC scan time with 1M pointer-free structs: 242.741µs
Notice that scanning 1,000,000 pointer-free structs took a fraction of the time. Because FlatTicket contains no pointers, the Go runtime marks its backing array as noscan, meaning the garbage collector marks the slice allocation in a single step without inspecting its individual fields.

